import { readFileSync } from 'node:fs'
const code = readFileSync(new URL('../lib/client.js', import.meta.url), 'utf8')
// Syntax check the bundle (it's CJS wrapped in a loader handoff; parse only)
new Function(code)
console.log('bundle parses OK')
if (!code.includes('window.__ModuleLoader__.load({')) throw new Error('missing loader handoff')
if (!code.includes('id: "dsh-tavily-web-search"')) throw new Error('missing plugin id')
if (!code.includes('settings.section')) throw new Error('missing settings section registration')
if (code.includes('settings.plugins.tab')) throw new Error('obsolete plugins tab registration remains')
if (!code.includes('addKey')) throw new Error('missing multi-key manager')
if (!code.includes('refreshAllUsage')) throw new Error('missing usage refresh')
if (code.includes('apiKeyConfigured')) throw new Error('legacy standalone key state remains')
if (code.includes('DEFAULT_API_KEY_REF')) throw new Error('legacy key fallback remains')
if (!code.includes('credentials.set')) throw new Error('missing credentials write')
console.log('handoff shape OK')
console.log('settings section registration OK')
console.log('credentials write OK')
